/// The Distinct function defined in fun.fbs is for use in cases like:
/// SELECT COUNT(DISTINCT c0), SUM(c1) FROM t GROUP BY c2;
/// The `distinct` field here on the query element is to be used to remove duplicate rows, like:
/// SELECT DISTINCT * FROM t;
/// or
/// SELECT DISTINCT ON (c0, c1) FROM t;
#[derive(Default, PartialEq, Debug, Clone)]
pub struct Distinct {
    /// If `on` is unset or has length 0, then the distinct is:
    /// SELECT DISTINCT * FROM t;
    /// If `on` has length > 0, then distinct is:
    /// SELECT DISTINCT ON (c0, c1) FROM t;
    on: Option<Vec<Expr>>,
}

impl Distinct {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsDistinct<'a>> {
        use crate::types::generated::query_generated::DistinctBuilder as FbsDistinctBuilder;

        let on_offset = self.on.as_ref().map(|v| {
            let mut on_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                on_offsets.push(offset);
            }
            let on_offset = builder.create_vector(&on_offsets);
            on_offset
        });

        let mut bldr = FbsDistinctBuilder::new(builder);
        if let Some(offset) = on_offset {
            bldr.add_on(offset);
        }
        bldr.finish()
    }
}

impl From<FbsDistinct<'_>> for Distinct {
    fn from(fbs: FbsDistinct<'_>) -> Self {
        let on = if let Some(val) = fbs.on() {
            let mut on = Vec::new();
            for elem in val {
                on.push(elem.into());
            }

            Some(on)
        } else {
            None
        };

        Self {
            on,
        }
    }
}

