#[derive(Default, PartialEq, Debug, Clone)]
pub struct UnaryQueryElement {
    distinct: Option<Distinct>,
    fields: Option<Vec<Expr>>,
    filter: Option<Function>,
    group_by: Option<Vec<Expr>>,
    joins: Option<Vec<Join>>,
    limit: u32,
    order_by: Option<Vec<TableOrderBy>>,
    sources: Vec<TableSource>,
}

impl UnaryQueryElement {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsUnaryQueryElement<'a>> {
        use crate::types::generated::query_generated::UnaryQueryElementBuilder as FbsUnaryQueryElementBuilder;

        let distinct_offset = self.distinct.as_ref().map(|o| o.serialize_to(builder));
        let fields_offset = self.fields.as_ref().map(|v| {
            let mut fields_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                fields_offsets.push(offset);
            }
            let fields_offset = builder.create_vector(&fields_offsets);
            fields_offset
        });
        let filter_offset = self.filter.as_ref().map(|o| o.serialize_to(builder));
        let group_by_offset = self.group_by.as_ref().map(|v| {
            let mut group_by_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                group_by_offsets.push(offset);
            }
            let group_by_offset = builder.create_vector(&group_by_offsets);
            group_by_offset
        });
        let joins_offset = self.joins.as_ref().map(|v| {
            let mut joins_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                joins_offsets.push(offset);
            }
            let joins_offset = builder.create_vector(&joins_offsets);
            joins_offset
        });
        let order_by_offset = self.order_by.as_ref().map(|v| {
            let mut order_by_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                order_by_offsets.push(offset);
            }
            let order_by_offset = builder.create_vector(&order_by_offsets);
            order_by_offset
        });
        let mut sources_offsets = Vec::with_capacity(self.sources.len());
        for val in self.sources.iter() {
            let offset = val.serialize_to(builder);
            sources_offsets.push(offset);
        }
        let sources_offset = builder.create_vector(&sources_offsets);

        let mut bldr = FbsUnaryQueryElementBuilder::new(builder);
        if let Some(offset) = distinct_offset {
            bldr.add_distinct(offset);
        }
        if let Some(offset) = fields_offset {
            bldr.add_fields(offset);
        }
        if let Some(offset) = filter_offset {
            bldr.add_filter(offset);
        }
        if let Some(offset) = group_by_offset {
            bldr.add_group_by(offset);
        }
        if let Some(offset) = joins_offset {
            bldr.add_joins(offset);
        }
        bldr.add_limit(self.limit);
        if let Some(offset) = order_by_offset {
            bldr.add_order_by(offset);
        }
        bldr.add_sources(sources_offset);
        bldr.finish()
    }
}

impl From<FbsUnaryQueryElement<'_>> for UnaryQueryElement {
    fn from(fbs: FbsUnaryQueryElement<'_>) -> Self {
        let distinct = fbs.distinct().map(Distinct::from);
        let fields = if let Some(val) = fbs.fields() {
            let mut fields = Vec::new();
            for elem in val {
                fields.push(elem.into());
            }

            Some(fields)
        } else {
            None
        };

        let filter = fbs.filter().map(Function::from);
        let group_by = if let Some(val) = fbs.group_by() {
            let mut group_by = Vec::new();
            for elem in val {
                group_by.push(elem.into());
            }

            Some(group_by)
        } else {
            None
        };

        let joins = if let Some(val) = fbs.joins() {
            let mut joins = Vec::new();
            for elem in val {
                joins.push(elem.into());
            }

            Some(joins)
        } else {
            None
        };

        let limit = fbs.limit();
        let order_by = if let Some(val) = fbs.order_by() {
            let mut order_by = Vec::new();
            for elem in val {
                order_by.push(elem.into());
            }

            Some(order_by)
        } else {
            None
        };

        let mut sources = Vec::new();
        for elem in fbs.sources() {
            sources.push(elem.into());
        }

        Self {
            distinct,
            fields,
            filter,
            group_by,
            joins,
            limit,
            order_by,
            sources,
        }
    }
}

