#[derive(Default, PartialEq, Debug, Clone)]
pub struct Vector {
    /// List of vectordbs to query. If this is empty, query all available vectordbs.
    ids: Vec<ObjectId>,
    limit: Option<NullableUint>,
    /// Optionally limit the results to those with a distance value less than
    /// max_distance. We treat max_distance=0 as no limit.
    max_distance: f32,
    query: String,
}

impl Vector {
    pub fn serialize_to<'a>(&self, builder: &mut flatbuffers::FlatBufferBuilder<'a>) -> flatbuffers::WIPOffset<FbsVector<'a>> {
        use crate::types::generated::query_generated::VectorBuilder as FbsVectorBuilder;

        let mut ids_offsets = Vec::with_capacity(self.ids.len());
        for val in self.ids.iter() {
            let offset = val.serialize_to(builder);
            ids_offsets.push(offset);
        }
        let ids_offset = builder.create_vector(&ids_offsets);
        let limit_offset = self.limit.as_ref().map(|o| o.serialize_to(builder));
        let query_offset = builder.create_string(&self.query);

        let mut bldr = FbsVectorBuilder::new(builder);
        bldr.add_ids(ids_offset);
        if let Some(offset) = limit_offset {
            bldr.add_limit(offset);
        }
        bldr.add_max_distance(self.max_distance);
        bldr.add_query(query_offset);
        bldr.finish()
    }
}

impl From<FbsVector<'_>> for Vector {
    fn from(fbs: FbsVector<'_>) -> Self {
        let mut ids = Vec::new();
        for elem in fbs.ids() {
            ids.push(elem.into());
        }

        let limit = fbs.limit().map(NullableUint::from);
        let max_distance = fbs.max_distance();
        let query = fbs.query().to_owned();
        Self {
            ids,
            limit,
            max_distance,
            query,
        }
    }
}

